interface Image { display(): void }

class RealImage implements Image {
  constructor(private file: string) {}
  display() { console.log(`Showing ${this.file}`) }
}

class ImageProxy implements Image {
  private real?: RealImage
  constructor(private file: string) {}
  display() { if (!this.real) this.real = new RealImage(this.file); this.real.display() }
}

interface Service { fetch(id: string): Promise<string> }

class RealService implements Service {
  async fetch(id: string) { return fetch(`/api/${id}`).then(r => r.text()) }
}

class ServiceProxy implements Service {
  private cache = new Map<string,string>()
  constructor(private real: RealService) {}
  async fetch(id: string) {
    if (!this.authorized(id)) throw new Error('unauthorized')
    if (this.cache.has(id)) return this.cache.get(id)!
    const v = await this.real.fetch(id)
    this.cache.set(id, v)
    return v
  }
  private authorized(id: string) { return true }
}

